//! The read-only shadow through `Service::init` itself: a read-only service
//! over the disposable bank (PL_SHADOW_REFRESH_DSN) with the tiny ONNX
//! fixture model (PL_SHADOW_EMBED_FIXTURE, generated by
//! `harness/embedding_fixture.py` at 1024 dimensions; ONNX Runtime from
//! ORT_DYLIB_PATH). The service adopts a writer session as its storage,
//! since a read-only session needs the `pseudolife_shadow` role, which the
//! test login cannot create; every path under test is the read-only one,
//! chosen by the service's configuration.

use super::*;
use crate::shadow::tests::{CLEAR, DB, required, test_dsn, vector};

/// The fixture model and the runtime, or `None` to skip (a panic when the
/// database tests are required).
fn fixture_model() -> Option<PathBuf> {
    let model = std::env::var_os("PL_SHADOW_EMBED_FIXTURE").filter(|v| !v.is_empty());
    let runtime = std::env::var_os("ORT_DYLIB_PATH").filter(|v| !v.is_empty());
    match (model, runtime) {
        (Some(model), Some(_)) => Some(PathBuf::from(model)),
        _ if required() => panic!(
            "PL_SHADOW_REFRESH_REQUIRED=1 but PL_SHADOW_EMBED_FIXTURE or ORT_DYLIB_PATH is unset"
        ),
        _ => {
            eprintln!("PL_SHADOW_EMBED_FIXTURE or ORT_DYLIB_PATH unset: skipping service test");
            None
        }
    }
}

struct Shadow {
    service: Arc<Service>,
    side: tokio_postgres::Client,
    side_task: tokio::task::JoinHandle<()>,
    dir: PathBuf,
}

impl Shadow {
    async fn open(dsn: &str, model: &std::path::Path) -> Shadow {
        let defaults = Config::default();
        let config = Config {
            read_only: true,
            embedding: crate::config::EmbeddingConfig {
                model_name: "pseudolife-test/shadow-fixture".into(),
                backend: "onnx".into(),
                ..defaults.embedding.clone()
            },
            ..defaults
        };
        let dir = std::env::temp_dir().join(format!(
            "pl-shadow-service-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let service = Arc::new(Service::new(
            config,
            DaemonEnv::from_env(&|_| None).unwrap(),
            dir.clone(),
            dsn.to_string(),
            false,
        ));
        assert!(service.config.read_only);
        // What `install` sets at startup.
        let _ = service.handle.set(Arc::downgrade(&service));
        let storage = Arc::new(Storage::open(dsn).await.unwrap());
        storage.client().batch_execute(CLEAR).await.unwrap();
        let embedder = Embedder::load_config(&service.config.embedding, Some(model), 1).unwrap();
        assert_eq!(embedder.embedding_dim(), crate::bank::DIM);
        {
            let mut inner = service.inner.lock().await;
            inner.storage = Some(storage.clone());
            inner.embedder = Some(Arc::new(embedder));
        }
        service.update(|s| s.storage = Some(storage));
        let (side, side_task) = crate::storage::connect(
            &crate::storage::parse_dsn(dsn).unwrap(),
            std::time::Duration::from_secs(10),
        )
        .await
        .unwrap();
        Shadow {
            service,
            side,
            side_task,
            dir,
        }
    }

    async fn exec(&self, sql: &str) {
        self.side.batch_execute(sql).await.unwrap();
    }

    async fn insert(&self, text: &str, k: usize) -> i64 {
        self.side
            .query_one(
                "INSERT INTO entries (band, text, embedding, ts, source) \
                 VALUES ('flat', $1, $2::text::vector, $3, 'user') RETURNING id",
                &[&text, &vector(k), &(1000.0 + k as f64)],
            )
            .await
            .unwrap()
            .get(0)
    }

    /// The resident bank equals a fresh hydration, order included, and
    /// holds every id once.
    async fn assert_bank_matches(&self, ready: &Ready) {
        let raw = crate::startup::metadata(&self.side).await.unwrap();
        let (fresh, _) = crate::startup::candidate(
            &self.side,
            &self.service.config.memory,
            raw,
            crate::bank::DIM,
        )
        .await
        .unwrap();
        let bank = ready.bank.read().unwrap();
        let ids: Vec<i64> = bank.entries.iter().map(|e| e.id).collect();
        let unique: std::collections::BTreeSet<i64> = ids.iter().copied().collect();
        assert_eq!(
            ids.len(),
            unique.len(),
            "a resident entry is duplicated: {ids:?}"
        );
        assert_eq!(bank.entries_dump(), fresh.entries_dump());
        assert_eq!(ids, fresh.entries.iter().map(|e| e.id).collect::<Vec<_>>());
        assert_eq!(bank.matrix, fresh.matrix);
    }

    async fn close(self) {
        let storage = self.service.inner.lock().await.storage.take();
        self.service.update(|s| {
            s.storage = None;
            s.ready = None;
            s.startup = None;
        });
        self.service.inner.lock().await.ready = None;
        drop(self.side);
        let _ = self.side_task.await;
        // Closed now, releasing the writer lease before the next test opens.
        if let Some(storage) = storage {
            Arc::try_unwrap(storage)
                .ok()
                .expect("a ready service still holds the session")
                .close()
                .await;
        }
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

/// A request dropped while its refresh's bank patch runs must not release
/// the service lock under that patch: a second refresh would plan from the
/// old state and patch again (duplicate appends, older telemetry last).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn db_dropped_request_cannot_let_two_refreshes_overlap() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    let alpha = shadow.insert("alpha", 1).await;
    shadow.insert("beta", 2).await;
    shadow.service.ensure_init_inner().await.unwrap();
    // The writer's read path and an addition.
    shadow
        .exec(&format!(
            "UPDATE entries SET access_count = 5 WHERE id = {alpha}"
        ))
        .await;
    shadow.insert("gamma", 3).await;
    let (reached, patch_pending) = tokio::sync::oneshot::channel();
    let (release, released) = tokio::sync::oneshot::channel();
    *shadow.service.patch_gate.lock().unwrap() = Some((reached, released));
    // Past the probe reuse, so the awareness read probes and refreshes.
    tokio::time::sleep(SHADOW_PROBE_REUSE + Duration::from_millis(100)).await;
    let service = shadow.service.clone();
    let caller = tokio::spawn(async move { service.ready_if_initialized().await });
    tokio::time::timeout(Duration::from_secs(30), patch_pending)
        .await
        .expect("the refresh never reached its bank patch")
        .unwrap();
    // The client goes away while the patch is pending.
    caller.abort();
    let _ = caller.await;
    let service = shadow.service.clone();
    let mut second = tokio::spawn(async move { service.refresh_writer_session().await });
    let overlapped = tokio::time::timeout(Duration::from_secs(2), &mut second)
        .await
        .is_ok();
    release.send(()).unwrap();
    assert!(
        !overlapped,
        "a second refresh ran while the first one's bank patch was pending"
    );
    let ready = second.await.unwrap().unwrap();
    shadow.assert_bank_matches(&ready).await;
    // The recorded state matches the bank: nothing further to do.
    let again = shadow.service.refresh_writer_session().await.unwrap();
    assert!(
        Arc::ptr_eq(&again, &ready),
        "a settled shadow refreshed again"
    );
    drop((again, ready));
    shadow.close().await;
}

/// A failed version and meta pre-read is a retryable initialization
/// failure: recorded as not_ready, with the backoff armed.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_failed_preread_records_not_ready_and_backs_off() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    struct Fault;
    impl Drop for Fault {
        fn drop(&mut self) {
            crate::shadow::PREREAD_FAULT.store(false, std::sync::atomic::Ordering::SeqCst);
        }
    }
    crate::shadow::PREREAD_FAULT.store(true, std::sync::atomic::Ordering::SeqCst);
    let fault = Fault;
    let error = shadow.service.ensure_init_inner().await.err().unwrap();
    assert!(
        error.contains("version and meta pre-read failed: injected pre-read fault"),
        "{error}"
    );
    assert_eq!(
        shadow.service.snapshot().not_ready.as_deref(),
        Some(error.as_str())
    );
    let retry = shadow.service.ensure_init_inner().await.err().unwrap();
    assert!(retry.contains("next retry in"), "no backoff armed: {retry}");
    drop(fault);
    shadow.close().await;
}

/// A meta commit after `Service::init`'s own read of meta, before its
/// hydration, is caught by the next refresh (the cortex included).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_meta_commit_during_service_init_is_refreshed() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    shadow.insert("alpha", 1).await;
    let (release, gate) = tokio::sync::oneshot::channel();
    *shadow.service.preread_gate.lock().unwrap() = Some(gate);
    let service = shadow.service.clone();
    let init = tokio::spawn(async move { service.ensure_init().await });
    let deadline = Instant::now() + Duration::from_secs(30);
    while shadow.service.preread_gate.lock().unwrap().is_some() {
        assert!(Instant::now() < deadline, "init never read meta");
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    shadow
        .exec(
            "INSERT INTO meta (key, value) VALUES ('cortex_dream_cursor', '12.5'), \
             ('active_session_pointer', '{\"session_id\": \"s3\", \"ts\": 7}')",
        )
        .await;
    release.send(()).unwrap();
    let first = init.await.unwrap().unwrap();
    assert_eq!(
        first.startup.metadata["cortex_dream_cursor"],
        serde_json::json!(0.0),
        "init hydrated meta it had not read"
    );
    let ready = shadow.service.refresh_writer_session().await.unwrap();
    assert_eq!(
        ready.startup.metadata["cortex_dream_cursor"],
        serde_json::json!(12.5),
        "the meta commit during init was never refreshed"
    );
    assert_eq!(
        ready.startup.metadata["active_session"],
        serde_json::json!(["s3", 7.0])
    );
    assert_eq!(ready.cortex.snapshot().dream_cursor, 12.5);
    drop((first, ready));
    shadow.close().await;
}
